'use strict';
function renderImportedTrip(){document.querySelector('.home-city').textContent=chatTrip.destination;const homeTags=document.querySelector('.home-tags'),tripTags=document.querySelector('.trip-tags');homeTags.replaceChildren();tripTags.replaceChildren();for(const style of chatTrip.styles){for(const host of [homeTags,tripTags]){const tag=document.createElement('span');tag.textContent=style;host.append(tag)}}document.querySelector('.home-activity').textContent=chatTrip.days+'天出行 · '+(chatTrip.scene||'已同步穿搭偏好');document.querySelector('.home-dates').textContent=chatTrip.departure.replaceAll('-','.')+' — '+chatTrip.returnDate.replaceAll('-','.');document.querySelector('.trip .city').textContent='⌖ '+chatTrip.destination;document.querySelector('.trip summary>span:nth-child(2)').textContent=chatTrip.departure.slice(5)+' — '+chatTrip.returnDate.slice(5);document.querySelector('.trip-expanded').textContent=chatTrip.days+'天旅行 · 目的地：'+chatTrip.destination+(chatTrip.scene?'；情景：'+chatTrip.scene:'')+'；风格：'+(chatTrip.styles.join('、')||'未选择');}
renderImportedTrip();const demoNote=document.createElement('p');demoNote.className='chat-demo-note';demoNote.textContent='穿搭对话演示';document.querySelector('.composer-wrap').append(demoNote);
